// lib/spice-commands/BJTCommand.ts
var BJTCommand = class {
  commandName = "bjt";
  props;
  constructor(props) {
    this.props = props;
  }
  toSpiceString() {
    const { name, collector, base, emitter, substrate, model, area } = this.props;
    let spiceString = `Q${name} ${collector} ${base} ${emitter}`;
    if (substrate) {
      spiceString += ` ${substrate}`;
    }
    spiceString += ` ${model}`;
    if (area) {
      spiceString += ` ${area}`;
    }
    return spiceString;
  }
};

