// lib/processors/simple-mosfet.ts
var processSimpleMosfet = ({
  netlist,
  component,
  componentPorts,
  nodeMap
}) => {
  if ("name" in component) {
    const drainPort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "drain" || p.port_hints?.includes("drain")
    );
    const gatePort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "gate" || p.port_hints?.includes("gate")
    );
    const sourcePort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "source" || p.port_hints?.includes("source")
    );
    const drainNode = nodeMap.get(drainPort?.source_port_id ?? "") || "0";
    const gateNode = nodeMap.get(gatePort?.source_port_id ?? "") || "0";
    const sourceNode = nodeMap.get(sourcePort?.source_port_id ?? "") || "0";
    const substrateNode = sourceNode;
    const channel_type = component.channel_type ?? "n";
    const mosfet_mode = component.mosfet_mode ?? "enhancement";
    const modelType = `${channel_type.toUpperCase()}MOS`;
    const modelName = `${modelType}_${mosfet_mode.toUpperCase()}`;
    if (!netlist.models.has(modelName)) {
      if (mosfet_mode === "enhancement") {
        const vto = channel_type === "p" ? -1 : 1;
        netlist.models.set(
          modelName,
          `.MODEL ${modelName} ${modelType} (VTO=${vto} KP=0.1)`
        );
      } else {
        netlist.models.set(
          modelName,
          `.MODEL ${modelName} ${modelType} (KP=0.1)`
        );
      }
    }
    const mosfetCmd = new MOSFETCommand({
      name: component.name,
      drain: drainNode,
      gate: gateNode,
      source: sourceNode,
      substrate: substrateNode,
      model: modelName
    });
    return new SpiceComponent(component.name, mosfetCmd, [
      drainNode,
      gateNode,
      sourceNode
    ]);
  }
  return null;
};

// lib/processors/simple-transistor.ts
var processSimpleTransistor = ({
  netlist,
  component,
  componentPorts,
  nodeMap
}) => {
  if ("name" in component) {
    const collectorPort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "collector" || p.port_hints?.includes("collector")
    );
    const basePort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "base" || p.port_hints?.includes("base")
    );
    const emitterPort = componentPorts.find(
      (p) => p.name?.toLowerCase() === "emitter" || p.port_hints?.includes("emitter")
    );
    if (!collectorPort || !basePort || !emitterPort) {
      throw new Error(
        `Transistor ${component.name} is missing required ports (collector, base, emitter)`
      );
    }
    const collectorNode = nodeMap.get(collectorPort.source_port_id) || "0";
    const baseNode = nodeMap.get(basePort.source_port_id) || "0";
    const emitterNode = nodeMap.get(emitterPort.source_port_id) || "0";
    const transistor_type = component.transistor_type ?? "npn";
    const modelName = transistor_type.toUpperCase();
    if (!netlist.models.has(modelName)) {
      netlist.models.set(
        modelName,
        `.MODEL ${modelName} ${transistor_type.toUpperCase()}`
      );
    }
    const bjtCmd = new BJTCommand({
      name: component.name,
      collector: collectorNode,
      base: baseNode,
      emitter: emitterNode,
      model: modelName
    });
    return new SpiceComponent(component.name, bjtCmd, [
      collectorNode,
      baseNode,
      emitterNode
    ]);
  }
  return null;
};

// lib/processors/process-simulation-voltage-sources.ts
var processSimulationVoltageSources = (netlist, simulationVoltageSources, nodeMap) => {
  for (const simSource of simulationVoltageSources) {
    if (simSource.type !== "simulation_voltage_source") continue;
    if (simSource.is_dc_source === false) {
      if ("terminal1_source_port_id" in simSource && "terminal2_source_port_id" in simSource && simSource.terminal1_source_port_id && simSource.terminal2_source_port_id) {
        const positiveNode = nodeMap.get(simSource.terminal1_source_port_id) || "0";
        const negativeNode = nodeMap.get(simSource.terminal2_source_port_id) || "0";
        let value = "";
        const wave_shape = simSource.wave_shape;
        if (wave_shape === "sinewave") {
          const v_offset = 0;
          const v_peak = simSource.voltage ?? 0;
          const freq = simSource.frequency ?? 0;
          const delay = 0;
          const damping_factor = 0;
          const phase = simSource.phase ?? 0;
          if (freq > 0) {
            value = `SIN(${v_offset} ${v_peak} ${freq} ${delay} ${damping_factor} ${phase})`;
          } else {
            value = `DC ${simSource.voltage ?? 0}`;
          }
        } else if (wave_shape === "square") {
          const v_initial = 0;
          const v_pulsed = simSource.voltage ?? 0;
          const freq = simSource.frequency ?? 0;
          const period_from_freq = freq === 0 ? Infinity : 1 / freq;
          const period = period_from_freq;
          const duty_cycle = simSource.duty_cycle ?? 0.5;
          const pulse_width = period * duty_cycle;
          const delay = 0;
          const rise_time = "1n";
          const fall_time = "1n";
          value = `PULSE(${v_initial} ${v_pulsed} ${delay} ${rise_time} ${fall_time} ${pulse_width} ${period})`;
        } else if (simSource.voltage !== void 0) {
          value = `DC ${simSource.voltage}`;
        }
        if (value) {
          const voltageSourceCmd = new VoltageSourceCommand({
            name: simSource.simulation_voltage_source_id,
            positiveNode,
            negativeNode,
            value
          });
          const spiceComponent = new SpiceComponent(
            simSource.simulation_voltage_source_id,
            voltageSourceCmd,
            [positiveNode, negativeNode]
          );
          netlist.addComponent(spiceComponent);
        }
      }
    } else {
      const positivePortId = simSource.positive_source_port_id;
      const negativePortId = simSource.negative_source_port_id;
      if (positivePortId && negativePortId && "voltage" in simSource && simSource.voltage !== void 0) {
        const positiveNode = nodeMap.get(positivePortId) || "0";
        const negativeNode = nodeMap.get(negativePortId) || "0";
        const voltageSourceCmd = new VoltageSourceCommand({
          name: simSource.simulation_voltage_source_id,
          positiveNode,
          negativeNode,
          value: `DC ${simSource.voltage}`
        });
        const spiceComponent = new SpiceComponent(
          simSource.simulation_voltage_source_id,
          voltageSourceCmd,
          [positiveNode, negativeNode]
        );
        netlist.addComponent(spiceComponent);
      }
    }
  }
};

